def compute(vars):
    total_current_2017 = vars["v1"]
    total_current_2018 = vars["v2"]
    change = total_current_2018 - total_current_2017

    return {
        "value": change,
        "trace": {
            "total_current_2017": total_current_2017,
            "total_current_2018": total_current_2018,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
